public static class __Judge
{
    const int Max = 500;

    static void Run(string id, System.Func<string> body)
    {
        string err;
        try { err = body(); }
        catch (System.Exception e) { err = "예외 발생: " + e.GetType().Name; }
        System.Console.WriteLine(err == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + err);
    }

    sealed class World
    {
        public MonsterGrid G;
        public float[] X = new float[Max], Y = new float[Max];
        public bool[] Alive = new bool[Max];
        public System.Collections.Generic.List<int> Buf = new System.Collections.Generic.List<int>(Max + 16);
        public World(float cell) { G = new MonsterGrid(-64f, -64f, 64f, 64f, cell, Max); }
        public void Put(int id, float x, float y)
        {
            if (Alive[id]) G.Update(id, x, y); else G.Insert(id, x, y);
            X[id] = x; Y[id] = y; Alive[id] = true;
        }
        // 전수 검사와 비교. 같으면 null, 다르면 사유.
        public string Query(float cx, float cy, float r)
        {
            Buf.Clear();
            int n = G.QueryCircle(cx, cy, r, Buf);
            if (n != Buf.Count) return "반환값(" + n + ")과 results.Count(" + Buf.Count + ")가 다름";
            var exp = new System.Collections.Generic.List<int>();
            for (int i = 0; i < Max; i++)
            {
                if (!Alive[i]) continue;
                float dx = X[i] - cx, dy = Y[i] - cy;
                if (dx * dx + dy * dy <= r * r) exp.Add(i);
            }
            Buf.Sort();
            bool same = exp.Count == Buf.Count;
            for (int i = 0; same && i < exp.Count; i++) same = exp[i] == Buf[i];
            if (same) return null;
            return "중심 (" + cx + ", " + cy + ") 반지름 " + r + ": 기대 [" + string.Join(",", exp) + "], 결과 [" + string.Join(",", Buf) + "]";
        }
    }

    public static void Main()
    {
        Run("negative-coords", () =>
        {
            var w = new World(4f);
            w.Put(0, -0.5f, -0.5f); w.Put(1, -3.9f, -0.1f); w.Put(2, -4.1f, -7.9f);
            w.Put(3, 0.5f, 0.5f); w.Put(4, -63.5f, -63.5f); w.Put(5, -8f, -8f);
            return w.Query(-2f, -2f, 2.5f) ?? w.Query(-0.5f, -0.5f, 0.25f) ?? w.Query(-5f, -7f, 3.5f)
                ?? w.Query(-63f, -63f, 1f) ?? w.Query(0.25f, 0.25f, 1.5f);
        });

        Run("radius-boundary", () =>
        {
            var w = new World(4f);
            w.Put(0, 3f, 4f); w.Put(1, -3f, -4f); w.Put(2, 3.0001f, 4f); w.Put(3, 0f, 5f); w.Put(4, 5.5f, 0f);
            string e = w.Query(0f, 0f, 5f);
            if (e != null) return "거리 == 반지름은 포함, 조금이라도 넘으면 제외여야 함. " + e;
            return w.Query(3f, 4f, 0f);
        });

        Run("multi-cell-circle", () =>
        {
            var w = new World(4f);
            int id = 0;
            for (int gy = -9; gy <= 9; gy++)
                for (int gx = -9; gx <= 9; gx++)
                    w.Put(id++, gx * 6.5f, gy * 6.5f);
            return w.Query(1f, -2f, 20f) ?? w.Query(-30f, 30f, 37.5f) ?? w.Query(0f, 0f, 100000f) ?? w.Query(60f, 60f, 9f);
        });

        Run("move-across-cells", () =>
        {
            var w = new World(4f);
            w.Put(0, -0.5f, -0.5f); w.Put(1, 1f, 1f);
            w.Put(0, -4.5f, -0.5f);
            string e = w.Query(-4.5f, -0.5f, 0.1f) ?? w.Query(-0.5f, -0.5f, 0.1f) ?? w.Query(0f, 0f, 10f);
            if (e != null) return "Update 로 셀을 넘어간 뒤 결과가 틀림. " + e;
            w.Put(0, -4.4f, -0.6f);
            w.Put(0, 30f, -30f);
            e = w.Query(30f, -30f, 1f) ?? w.Query(0f, 0f, 10f);
            if (e != null) return "여러 번 이동한 뒤 결과가 틀림. " + e;
            if (!w.G.Remove(1)) return "등록된 몬스터의 Remove 가 false 를 반환";
            w.Alive[1] = false;
            if (w.G.Remove(1)) return "이미 제거한 몬스터의 Remove 가 true 를 반환";
            return w.Query(0f, 0f, 100f);
        });

        Run("out-of-bounds", () =>
        {
            var w = new World(4f);
            w.Put(0, 500f, 500f); w.Put(1, -500f, 0f); w.Put(2, 0f, 0f); w.Put(3, 1e15f, -1e15f); w.Put(4, 64f, 64f);
            return w.Query(499f, 499f, 2f) ?? w.Query(-498f, 0f, 2.5f) ?? w.Query(0f, 0f, 1000f)
                ?? w.Query(63f, 63f, 2f) ?? w.Query(1e15f, -1e15f, 1f) ?? w.Query(60f, 60f, 1e15f);
        });

        Run("buffer-reuse", () =>
        {
            var w = new World(4f);
            w.Put(0, 1f, 1f); w.Put(1, 2f, 2f);
            var buf = new System.Collections.Generic.List<int>(Max + 16);
            buf.Add(777); buf.Add(888);
            int n = w.G.QueryCircle(0f, 0f, 5f, buf);
            if (n != 2 || buf.Count != 2 || buf.Contains(777) || buf.Contains(888))
                return "이전 호출의 내용이 results 에 남아 있음 (먼저 Clear 해야 함)";
            n = w.G.QueryCircle(50f, 50f, 1f, buf);
            if (n != 0 || buf.Count != 0) return "빈 결과일 때 results 가 비워지지 않음";
            return null;
        });

        Run("no-alloc-query", () =>
        {
            var w = new World(4f);
            var rng = new System.Random(42);
            for (int i = 0; i < Max; i++) w.Put(i, (float)(rng.NextDouble() * 128 - 64), (float)(rng.NextDouble() * 128 - 64));
            var buf = new System.Collections.Generic.List<int>(Max + 16);
            for (int i = 0; i < 300; i++) w.G.QueryCircle((i % 100) - 50, (i % 77) - 38, 6f, buf);
            w.G.QueryCircle(0f, 0f, 1000f, buf);
            long before = System.GC.GetAllocatedBytesForCurrentThread();
            for (int i = 0; i < 2000; i++) w.G.QueryCircle((i % 100) - 50, (i % 77) - 38, 6f, buf);
            long bytes = System.GC.GetAllocatedBytesForCurrentThread() - before;
            return bytes == 0 ? null : "QueryCircle 2000회 동안 " + bytes + "바이트 할당됨 (질의 중 할당 금지)";
        });

        Run("random-vs-bruteforce", () =>
        {
            var rng = new System.Random(777);
            float[] cells = { 1f, 3.7f, 8f, 16f };
            foreach (float cell in cells)
            {
                var w = new World(cell);
                for (int step = 0; step < 1500; step++)
                {
                    int id = rng.Next(Max);
                    int op = rng.Next(100);
                    if (w.Alive[id] && op < 20) { w.G.Remove(id); w.Alive[id] = false; }
                    else
                    {
                        int k = rng.Next(100);
                        float x = k < 75 ? (float)(rng.NextDouble() * 128 - 64) : k < 90 ? rng.Next(-70, 71) : (float)(rng.NextDouble() * 600 - 300);
                        k = rng.Next(100);
                        float y = k < 75 ? (float)(rng.NextDouble() * 128 - 64) : k < 90 ? rng.Next(-70, 71) : (float)(rng.NextDouble() * 600 - 300);
                        w.Put(id, x, y);
                    }
                    if (step % 3 != 0) continue;
                    float cx = (float)(rng.NextDouble() * 160 - 80), cy = (float)(rng.NextDouble() * 160 - 80);
                    int rk = rng.Next(100);
                    float r = rk < 10 ? 0f : rk < 70 ? (float)(rng.NextDouble() * 12) : rk < 90 ? rng.Next(0, 30) : (float)(rng.NextDouble() * 400);
                    string e = w.Query(cx, cy, r);
                    if (e != null) return "cellSize " + cell + ", " + step + "번째 연산 후: " + (e.Length > 160 ? e.Substring(0, 160) + "..." : e);
                }
            }
            return null;
        });
    }
}

