using System;
using System.Collections.Generic;
public struct HeapEntry { public int Id; public long Priority; }
// Priority 가 가장 작은 항목이 먼저 나온다. 같은 Id 는 동시에 하나만 들어 있다.
public sealed class MinHeap
{
    private readonly List<HeapEntry> _heap = new List<HeapEntry>();
    public int Count => _heap.Count;
    public void Push(int id, long priority)
    {
        _heap.Add(new HeapEntry { Id = id, Priority = priority });
        SiftUp(_heap.Count - 1);
    }

    public HeapEntry Pop()
    {
        if (_heap.Count == 0) throw new InvalidOperationException("heap is empty");
        HeapEntry top = _heap[0];
        int last = _heap.Count - 1;
        _heap[0] = _heap[last];
        _heap.RemoveAt(last);
        if (_heap.Count > 1) SiftDown(0);
        return top;
    }

    public bool Update(int id, long newPriority)
    {
        for (int i = 0; i < _heap.Count; i++)
        {
            if (_heap[i].Id != id) continue;
            _heap[i] = new HeapEntry { Id = id, Priority = newPriority };
            SiftUp(i);
            return true;
        }
        return false;
    }

    private static bool Less(HeapEntry a, HeapEntry b) => a.Priority < b.Priority;
    private void SiftUp(int i)
    {
        while (i > 0)
        {
            int parent = (i - 1) / 2;
            if (!Less(_heap[i], _heap[parent])) break;
            (_heap[i], _heap[parent]) = (_heap[parent], _heap[i]);
            i = parent;
        }
    }

    private void SiftDown(int i)
    {
        while (true)
        {
            int child = 2 * i + 1;
            if (child >= _heap.Count || !Less(_heap[child], _heap[i])) break;
            (_heap[i], _heap[child]) = (_heap[child], _heap[i]);
            i = child;
        }
    }
}

