public static class __Judge
{
    static void Run(string id, System.Func<string> body)
    {
        string err;
        try { err = body(); }
        catch (System.Exception e) { err = "예외 발생: " + e.GetType().Name; }
        System.Console.WriteLine(err == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + err);
    }

    // 행 문자열로 맵을 만든다. '#' = 벽(0), '1'..'9' = 진입 비용
    static int[,] Map(params string[] rows)
    {
        var m = new int[rows.Length, rows[0].Length];
        for (int y = 0; y < rows.Length; y++)
            for (int x = 0; x < rows[0].Length; x++)
                m[y, x] = rows[y][x] == '#' ? 0 : rows[y][x] - '0';
        return m;
    }

    // 기준 답: 변화가 없을 때까지 완화를 반복한다(느리지만 단순). 도달 불가면 -1
    static int RefCost(int[,] m, int sx, int sy, int gx, int gy)
    {
        int h = m.GetLength(0), w = m.GetLength(1);
        if (sx < 0 || sy < 0 || sx >= w || sy >= h || gx < 0 || gy < 0 || gx >= w || gy >= h) return -1;
        if (m[sy, sx] == 0 || m[gy, gx] == 0) return -1;
        var d = RefDist(m, sx, sy);
        return d[gy, gx] == int.MaxValue ? -1 : d[gy, gx];
    }

    // start 에서 각 타일까지의 최소 비용(도달 불가는 int.MaxValue). start 는 맵 안의 벽이 아닌 타일이어야 한다
    static int[,] RefDist(int[,] m, int sx, int sy)
    {
        int h = m.GetLength(0), w = m.GetLength(1);
        var d = new int[h, w];
        for (int y = 0; y < h; y++) for (int x = 0; x < w; x++) d[y, x] = int.MaxValue;
        d[sy, sx] = 0;
        int[] dx = { 1, -1, 0, 0 }, dy = { 0, 0, 1, -1 };
        bool changed = true;
        while (changed)
        {
            changed = false;
            for (int y = 0; y < h; y++) for (int x = 0; x < w; x++)
            {
                if (d[y, x] == int.MaxValue) continue;
                for (int k = 0; k < 4; k++)
                {
                    int nx = x + dx[k], ny = y + dy[k];
                    if (nx < 0 || ny < 0 || nx >= w || ny >= h || m[ny, nx] == 0) continue;
                    if (d[y, x] + m[ny, nx] < d[ny, nx]) { d[ny, nx] = d[y, x] + m[ny, nx]; changed = true; }
                }
            }
        }
        return d;
    }

    static string Desc(int[,] m, int sx, int sy, int gx, int gy)
    {
        int h = m.GetLength(0), w = m.GetLength(1);
        string ends = " (" + sx + "," + sy + ")->(" + gx + "," + gy + ")";
        if (w * h > 100) return "맵 " + w + "x" + h + ends;
        var sb = new System.Text.StringBuilder("맵 ");
        for (int y = 0; y < h; y++)
        {
            for (int x = 0; x < w; x++) sb.Append(m[y, x] == 0 ? '#' : (char)('0' + m[y, x]));
            if (y < h - 1) sb.Append('/');
        }
        return sb.Append(ends).ToString();
    }

    // 경로가 유효하고 비용이 최소인지 검사한다. 최소 비용 경로가 여러 개면 어느 것이든 통과한다.
    static string Check(int[,] m, int sx, int sy, int gx, int gy, out int expanded)
    {
        int h = m.GetLength(0), w = m.GetLength(1);
        var copy = (int[,])m.Clone();
        var path = TilePathfinder.FindPath(m, (sx, sy), (gx, gy), out expanded);
        string where = Desc(copy, sx, sy, gx, gy);
        if (path == null) return where + " : null 을 반환함(빈 리스트여야 함)";
        for (int y = 0; y < h; y++) for (int x = 0; x < w; x++) if (m[y, x] != copy[y, x]) return where + " : 입력 cost 배열을 변경함";
        int best = RefCost(m, sx, sy, gx, gy);
        if (best < 0) return path.Count == 0 ? null : where + " : 경로가 없어야 하는데 길이 " + path.Count + " 인 경로를 반환";
        if (path.Count == 0) return where + " : 경로가 있는데(최소 비용 " + best + ") 빈 리스트를 반환";
        if (path[0].x != sx || path[0].y != sy) return where + " : 첫 원소가 start 가 아님 (" + path[0].x + "," + path[0].y + ")";
        var last = path[path.Count - 1];
        if (last.x != gx || last.y != gy) return where + " : 마지막 원소가 goal 이 아님 (" + last.x + "," + last.y + ")";
        int total = 0;
        for (int i = 1; i < path.Count; i++)
        {
            int px = path[i].x, py = path[i].y;
            if (px < 0 || py < 0 || px >= w || py >= h || m[py, px] == 0) return where + " : 경로가 벽이나 맵 밖 (" + px + "," + py + ") 을 지남";
            if (System.Math.Abs(px - path[i - 1].x) + System.Math.Abs(py - path[i - 1].y) != 1) return where + " : " + i + "번째 걸음이 상하좌우 한 칸 이동이 아님";
            total += m[py, px];
        }
        if (total != best) return where + " : 최소 비용 " + best + " / 반환한 경로의 비용 " + total;
        if (expanded < 1 || expanded > w * h) return where + " : expanded 가 1..타일 수 범위를 벗어남 (" + expanded + ")";
        return null;
    }

    static string Check(int[,] m, int sx, int sy, int gx, int gy) { int e; return Check(m, sx, sy, gx, gy, out e); }

    public static void Main()
    {
        Run("basic-path-around-wall", () =>
            Check(Map("111", "1#1", "111"), 0, 0, 2, 2)
            ?? Check(Map("1111", "###1", "1111", "1###", "1111"), 0, 0, 3, 4)
            ?? Check(Map("11111"), 4, 0, 0, 0));

        Run("weighted-terrain", () =>
            // 늪(9)을 돌아가는 편이 싼 맵, 늪(5)을 가로지르는 편이 싼 맵 등
            Check(Map("11111", "19991", "19991", "11111"), 0, 1, 4, 1)
            ?? Check(Map("1111111", "1#####1", "1555551", "1#####1", "1111111"), 0, 2, 6, 2)
            ?? Check(Map("131", "111", "191"), 1, 0, 1, 2)
            ?? Check(Map("1911", "1191", "9111"), 0, 0, 3, 2)
            // 먼저 발견한 경로보다 나중에 발견한 경로가 더 싼 맵
            ?? Check(Map("31131321", "112113##", "2#322313", "32321311", "#233##21"), 4, 2, 0, 2));

        Run("start-equals-goal", () =>
        {
            int e;
            var p = TilePathfinder.FindPath(Map("11", "11"), (1, 1), (1, 1), out e);
            if (p == null || p.Count != 1 || p[0].x != 1 || p[0].y != 1) return "start == goal 이면 [start] 한 칸짜리 경로여야 함. 결과 길이 " + (p == null ? "null" : p.Count.ToString());
            return Check(Map("5"), 0, 0, 0, 0);
        });

        Run("unreachable-returns-empty", () =>
            Check(Map("11#1", "11#1", "11#1"), 0, 0, 3, 2)
            ?? Check(Map("111", "1#1", "#1#"), 0, 0, 1, 2)
            ?? Check(Map("1#1"), 0, 0, 2, 0));

        Run("invalid-endpoints", () =>
            Check(Map("#11", "111"), 0, 0, 2, 1)       // start 가 벽
            ?? Check(Map("111", "11#"), 0, 0, 2, 1)    // goal 이 벽
            ?? Check(Map("111", "111"), -1, 0, 2, 1)   // start 가 맵 밖
            ?? Check(Map("111", "111"), 0, 0, 3, 1)    // goal 이 맵 밖
            ?? Check(Map("111", "111"), 0, 0, 1, 2));

        Run("tie-break-open-field", () =>
        {
            // 장애물 없는 30x30 평지는 f 동률투성이다. 동률에서 h 가 작은 쪽을 먼저 꺼내면 경로 길이만큼만 확장한다.
            var m = new int[30, 30];
            for (int y = 0; y < 30; y++) for (int x = 0; x < 30; x++) m[y, x] = 1;
            int[][] q = { new[] { 0, 0, 29, 29 }, new[] { 29, 0, 0, 29 }, new[] { 29, 29, 0, 0 }, new[] { 3, 25, 27, 2 } };
            foreach (var c in q)
            {
                int e;
                string err = Check(m, c[0], c[1], c[2], c[3], out e);
                if (err != null) return err;
                int tiles = System.Math.Abs(c[0] - c[2]) + System.Math.Abs(c[1] - c[3]) + 1;
                if (e > 2 * tiles) return "평지 30x30 (" + c[0] + "," + c[1] + ")->(" + c[2] + "," + c[3] + "): 경로는 " + tiles + "칸인데 " + e + "칸을 확장함(허용 " + (2 * tiles) + " 이하). 휴리스틱과 f 동률 처리를 확인";
            }
            return null;
        });

        Run("expanded-counts-each-tile-once", () =>
        {
            // 맨해튼 휴리스틱의 A* 가 goal 을 꺼낼 때까지 처리하는 타일은 구현 방식과 무관하게 범위가 정해진다.
            // f* = (start 에서의 최소 비용 + 맨해튼 거리) 가 경로 비용보다 작은 타일은 반드시 처리되고, 큰 타일은 처리되지 않는다.
            uint s = 31337u;
            System.Func<int, int> rnd = n => { s = s * 1664525u + 1013904223u; return (int)((s >> 8) % (uint)n); };
            for (int run = 0; run < 300; run++)
            {
                int w = 3 + rnd(10), h = 3 + rnd(10);
                int maxCost = run % 2 == 0 ? 9 : 4;
                var m = new int[h, w];
                for (int y = 0; y < h; y++) for (int x = 0; x < w; x++) m[y, x] = rnd(100) < 12 ? 0 : 1 + rnd(maxCost);
                int sx = rnd(w), sy = rnd(h), gx = rnd(w), gy = rnd(h);
                if (m[gy, gx] == 0) continue;
                m[sy, sx] = 1; // 맵의 최소 타일 비용을 항상 1 로 둔다(start 의 비용은 경로 비용에 들어가지 않는다)
                var d = RefDist(m, sx, sy);
                if (d[gy, gx] == int.MaxValue) continue;
                int best = d[gy, gx], must = 1, may = 0;
                for (int y = 0; y < h; y++) for (int x = 0; x < w; x++)
                {
                    if (d[y, x] == int.MaxValue) continue;
                    int f = d[y, x] + System.Math.Abs(x - gx) + System.Math.Abs(y - gy);
                    if (f < best) must++;
                    if (f <= best) may++;
                }
                int e;
                string err = Check(m, sx, sy, gx, gy, out e);
                if (err != null) return "무작위 " + run + "회차: " + err;
                if (e > may) return Desc(m, sx, sy, gx, gy) + " : expanded 가 " + e + " 인데, 타일을 한 번씩만 처리하면 많아야 " + may + " 이다. 낡은 항목을 건너뛰는지, 건너뛴 것을 세지 않는지 확인";
                if (e < must) return Desc(m, sx, sy, gx, gy) + " : expanded 가 " + e + " 인데, goal 을 꺼낼 때까지 적어도 " + must + " 타일을 처리해야 한다. 꺼내 처리할 때마다(goal 포함) 세는지, goal 을 꺼낼 때 끝내는지 확인";
            }
            return null;
        });

        Run("random-vs-reference", () =>
        {
            uint s = 20261122u;
            System.Func<int, int> rnd = n => { s = s * 1664525u + 1013904223u; return (int)((s >> 8) % (uint)n); };
            for (int run = 0; run < 400; run++)
            {
                int w = 1 + rnd(9), h = 1 + rnd(9);
                int maxCost = run % 3 == 0 ? 1 : (run % 3 == 1 ? 3 : 9);
                int wallPct = 10 + rnd(30);
                var m = new int[h, w];
                for (int y = 0; y < h; y++) for (int x = 0; x < w; x++) m[y, x] = rnd(100) < wallPct ? 0 : 1 + rnd(maxCost);
                string err = Check(m, rnd(w), rnd(h), rnd(w), rnd(h));
                if (err != null) return "무작위 " + run + "회차: " + err;
            }
            return null;
        });

        Run("large-map-optimal", () =>
        {
            // 100x100, 진입 비용 1~4, 벽 25%: 큰 맵에서도 최소 비용 경로인지 기준 답과 비교한다
            uint s = 777u;
            System.Func<int, int> rnd = n => { s = s * 1664525u + 1013904223u; return (int)((s >> 8) % (uint)n); };
            var m = new int[100, 100];
            for (int y = 0; y < 100; y++) for (int x = 0; x < 100; x++) m[y, x] = rnd(100) < 25 ? 0 : 1 + rnd(4);
            m[0, 0] = 1; m[99, 99] = 1; m[50, 50] = 1; m[0, 99] = 1; m[99, 0] = 1;
            return Check(m, 0, 0, 99, 99) ?? Check(m, 99, 0, 50, 50) ?? Check(m, 50, 50, 0, 99);
        });
    }
}

