using System;
using System.Collections.Generic;

public static class EightWayPathfinder
{
    public const int StraightCost = 10; // 상하좌우 한 칸
    public const int DiagonalCost = 14; // 대각선 한 칸

    private static readonly int[] Dx = { 1, 0, -1, 0, 1, -1, -1, 1 };
    private static readonly int[] Dy = { 0, 1, 0, -1, 1, 1, -1, -1 };

    // walkable[y, x] 가 true 인 칸만 지나갈 수 있다. 8방향 이동.
    // 대각선 이동은 도착 칸만 비어 있으면 허용한다.
    // 비용 합이 최소인 경로를 start 와 goal 을 포함해 start -> goal 순서로 반환한다.
    // 경로가 없거나 start / goal 이 맵 밖·벽이면 빈 리스트, start == goal 이면 원소 1개.
    public static List<(int x, int y)> FindPath(bool[,] walkable, (int x, int y) start, (int x, int y) goal)
    {
        var path = new List<(int x, int y)>();
        int height = walkable.GetLength(0), width = walkable.GetLength(1);
        if (!IsOpen(walkable, width, height, start.x, start.y)) return path;
        if (!IsOpen(walkable, width, height, goal.x, goal.y)) return path;

        int n = width * height;
        int startId = start.y * width + start.x;
        int goalId = goal.y * width + goal.x;

        var g = new int[n];
        var cameFrom = new int[n];
        var visited = new bool[n];
        for (int i = 0; i < n; i++) cameFrom[i] = -1;

        // 우선순위 (f, order): f 가 같으면 먼저 넣은 항목이 먼저 나온다.
        var open = new PriorityQueue<int, (int f, int order)>();
        int order = 0;
        visited[startId] = true;
        open.Enqueue(startId, (Heuristic(start.x, start.y, goal.x, goal.y), order++));

        while (open.Count > 0)
        {
            int cur = open.Dequeue();
            if (cur == goalId) break;

            int cx = cur % width, cy = cur / width;
            for (int d = 0; d < 8; d++)
            {
                int nx = cx + Dx[d], ny = cy + Dy[d];
                if (!IsOpen(walkable, width, height, nx, ny)) continue;
                int next = ny * width + nx;
                if (visited[next]) continue;
                visited[next] = true;

                int step = (Dx[d] != 0 && Dy[d] != 0) ? DiagonalCost : StraightCost;
                g[next] = g[cur] + step;
                cameFrom[next] = cur;
                open.Enqueue(next, (g[next] + Heuristic(nx, ny, goal.x, goal.y), order++));
            }
        }

        if (cameFrom[goalId] == -1) return path;
        for (int c = goalId; c != startId; c = cameFrom[c]) path.Add((c % width, c / width));
        return path;
    }

    private static bool IsOpen(bool[,] walkable, int width, int height, int x, int y)
    {
        return x >= 0 && y >= 0 && x < width && y < height && walkable[y, x];
    }

    private static int Heuristic(int x, int y, int gx, int gy)
    {
        int dx = Math.Abs(x - gx), dy = Math.Abs(y - gy);
        return StraightCost * (dx + dy);
    }
}

problems.solutionCode:
using System;
using System.Collections.Generic;

public static class EightWayPathfinder
{
    public const int StraightCost = 10; // 상하좌우 한 칸
    public const int DiagonalCost = 14; // 대각선 한 칸

    private static readonly int[] Dx = { 1, 0, -1, 0, 1, -1, -1, 1 };
    private static readonly int[] Dy = { 0, 1, 0, -1, 1, 1, -1, -1 };

    public static List<(int x, int y)> FindPath(bool[,] walkable, (int x, int y) start, (int x, int y) goal)
    {
        var path = new List<(int x, int y)>();
        int height = walkable.GetLength(0), width = walkable.GetLength(1);
        if (!IsOpen(walkable, width, height, start.x, start.y)) return path;
        if (!IsOpen(walkable, width, height, goal.x, goal.y)) return path;

        int n = width * height;
        int startId = start.y * width + start.x;
        int goalId = goal.y * width + goal.x;

        var g = new int[n];
        var cameFrom = new int[n];
        var closed = new bool[n]; // open list 에서 "꺼내 처리한" 칸만 표시한다
        for (int i = 0; i < n; i++) { g[i] = int.MaxValue; cameFrom[i] = -1; }

        // 우선순위 (f, order): f 가 같으면 먼저 넣은 항목이 먼저 나온다.
        var open = new PriorityQueue<int, (int f, int order)>();
        int order = 0;
        g[startId] = 0;
        open.Enqueue(startId, (Heuristic(start.x, start.y, goal.x, goal.y), order++));

        while (open.Count > 0)
        {
            int cur = open.Dequeue();
            if (closed[cur]) continue; // 더 싼 경로로 이미 처리한 칸의 낡은 항목
            closed[cur] = true;
            if (cur == goalId) break;

            int cx = cur % width, cy = cur / width;
            for (int d = 0; d < 8; d++)
            {
                int nx = cx + Dx[d], ny = cy + Dy[d];
                if (!IsOpen(walkable, width, height, nx, ny)) continue;
                int next = ny * width + nx;
                if (closed[next]) continue;

                int step = (Dx[d] != 0 && Dy[d] != 0) ? DiagonalCost : StraightCost;
                int ng = g[cur] + step;
                if (ng >= g[next]) continue; // 더 싸질 때만 갱신하고 다시 넣는다
                g[next] = ng;
                cameFrom[next] = cur;
                open.Enqueue(next, (ng + Heuristic(nx, ny, goal.x, goal.y), order++));
            }
        }

        if (g[goalId] == int.MaxValue) return path; // start == goal 이면 g 가 0 이라 통과한다
        for (int c = goalId; c != -1; c = cameFrom[c]) path.Add((c % width, c / width));
        path.Reverse(); // goal -> start 순서로 모았으므로 뒤집는다
        return path;
    }

    private static bool IsOpen(bool[,] walkable, int width, int height, int x, int y)
    {
        return x >= 0 && y >= 0 && x < width && y < height && walkable[y, x];
    }

    // 8방향 대각 거리(octile): 대각선으로 min(dx, dy) 번, 나머지는 직선으로 간다고 본 비용.
    // 장애물이 없을 때의 실제 최소 비용과 같으므로 실제 비용을 넘지 않는다.
    private static int Heuristic(int x, int y, int gx, int gy)
    {
        int dx = Math.Abs(x - gx), dy = Math.Abs(y - gy);
        return StraightCost * (dx + dy) + (DiagonalCost - 2 * StraightCost) * Math.Min(dx, dy);
    }
}

