public static class __Judge
{
    static void Run(string id, System.Func<string> body)
    {
        string err;
        try { err = body(); }
        catch (System.Exception e) { err = "예외 발생: " + e.GetType().Name; }
        System.Console.WriteLine(err == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + err);
    }

    // '.' = 지나갈 수 있는 칸, '#' = 벽
    static bool[,] Map(params string[] rows)
    {
        var m = new bool[rows.Length, rows[0].Length];
        for (int y = 0; y < rows.Length; y++)
            for (int x = 0; x < rows[0].Length; x++) m[y, x] = rows[y][x] != '#';
        return m;
    }

    // 기준 답: 변화가 없을 때까지 완화를 반복한다(느리지만 단순). 도달 불가면 -1
    static int RefCost(bool[,] m, int sx, int sy, int gx, int gy)
    {
        int h = m.GetLength(0), w = m.GetLength(1);
        if (sx < 0 || sy < 0 || sx >= w || sy >= h || gx < 0 || gy < 0 || gx >= w || gy >= h) return -1;
        if (!m[sy, sx] || !m[gy, gx]) return -1;
        var d = new int[h, w];
        for (int y = 0; y < h; y++) for (int x = 0; x < w; x++) d[y, x] = int.MaxValue;
        d[sy, sx] = 0;
        bool changed = true;
        while (changed)
        {
            changed = false;
            for (int y = 0; y < h; y++) for (int x = 0; x < w; x++)
            {
                if (d[y, x] == int.MaxValue) continue;
                for (int dy = -1; dy <= 1; dy++) for (int dx = -1; dx <= 1; dx++)
                {
                    int nx = x + dx, ny = y + dy;
                    if ((dx == 0 && dy == 0) || nx < 0 || ny < 0 || nx >= w || ny >= h || !m[ny, nx]) continue;
                    int c = d[y, x] + (dx != 0 && dy != 0 ? 14 : 10);
                    if (c < d[ny, nx]) { d[ny, nx] = c; changed = true; }
                }
            }
        }
        return d[gy, gx] == int.MaxValue ? -1 : d[gy, gx];
    }

    static string Desc(bool[,] m, int sx, int sy, int gx, int gy)
    {
        int h = m.GetLength(0), w = m.GetLength(1);
        var sb = new System.Text.StringBuilder("맵 ");
        for (int y = 0; y < h; y++)
        {
            for (int x = 0; x < w; x++) sb.Append(m[y, x] ? '.' : '#');
            if (y < h - 1) sb.Append('/');
        }
        return sb.Append(" (" + sx + "," + sy + ")->(" + gx + "," + gy + ")").ToString();
    }

    // 경로가 유효하고 비용이 최소인지 검사한다. 최소 비용 경로가 여러 개면 어느 것이든 통과한다.
    static string Check(bool[,] m, int sx, int sy, int gx, int gy)
    {
        int h = m.GetLength(0), w = m.GetLength(1);
        string where = Desc(m, sx, sy, gx, gy);
        var path = EightWayPathfinder.FindPath(m, (sx, sy), (gx, gy));
        if (path == null) return where + " : null 을 반환함(빈 리스트여야 함)";
        int best = RefCost(m, sx, sy, gx, gy);
        if (best < 0) return path.Count == 0 ? null : where + " : 경로가 없어야 하는데 길이 " + path.Count + " 인 경로를 반환";
        if (path.Count == 0) return where + " : 경로가 있는데(최소 비용 " + best + ") 빈 리스트를 반환";
        if (path[0].x != sx || path[0].y != sy) return where + " : 첫 원소가 start 가 아님 (" + path[0].x + "," + path[0].y + ")";
        var last = path[path.Count - 1];
        if (last.x != gx || last.y != gy) return where + " : 마지막 원소가 goal 이 아님 (" + last.x + "," + last.y + ")";
        int total = 0;
        for (int i = 1; i < path.Count; i++)
        {
            int px = path[i].x, py = path[i].y;
            if (px < 0 || py < 0 || px >= w || py >= h || !m[py, px]) return where + " : 경로가 벽이나 맵 밖 (" + px + "," + py + ") 을 지남";
            int ax = System.Math.Abs(px - path[i - 1].x), ay = System.Math.Abs(py - path[i - 1].y);
            if (ax > 1 || ay > 1 || ax + ay == 0) return where + " : " + i + "번째 걸음이 인접한 칸으로의 이동이 아님";
            total += ax + ay == 2 ? 14 : 10;
        }
        return total == best ? null : where + " : 최소 비용 " + best + " / 반환한 경로의 비용 " + total;
    }

    public static void Main()
    {
        Run("path-order-and-endpoints", () =>
            Check(Map("....."), 0, 0, 4, 0)
            ?? Check(Map("....."), 4, 0, 0, 0)
            ?? Check(Map(".", ".", "."), 0, 0, 0, 2)
            ?? Check(Map("..", ".."), 0, 0, 1, 1));

        Run("start-equals-goal", () =>
        {
            var p = EightWayPathfinder.FindPath(Map("...", "..."), (1, 1), (1, 1));
            if (p == null || p.Count != 1 || p[0].x != 1 || p[0].y != 1) return "start == goal 이면 [start] 한 칸짜리 경로여야 함. 결과 길이 " + (p == null ? "null" : p.Count.ToString());
            return Check(Map("."), 0, 0, 0, 0);
        });

        Run("unreachable-and-invalid-endpoints", () =>
            Check(Map("..#.", "..#.", "..#."), 0, 0, 3, 2)
            ?? Check(Map("#..", "..."), 0, 0, 2, 1)
            ?? Check(Map("...", "..#"), 0, 0, 2, 1)
            ?? Check(Map("...", "..."), -1, 0, 2, 1)
            ?? Check(Map("...", "..."), 0, 0, 2, 2));

        Run("open-field-diagonals", () =>
            Check(Map("......", "......", "......", "......"), 0, 0, 5, 3)
            ?? Check(Map("......", "......", "......", "......"), 5, 0, 0, 3)
            ?? Check(Map("....", "....", "....", "...."), 3, 3, 0, 0)
            ?? Check(Map("...", "..."), 0, 0, 2, 1));

        Run("heuristic-must-not-overestimate", () =>
            Check(Map("....", "..#.", "...."), 3, 0, 0, 2)
            ?? Check(Map("....", ".#..", "...."), 0, 0, 3, 2)
            ?? Check(Map(".....", "..#..", ".....", "....."), 4, 0, 0, 3));

        Run("cheaper-path-found-later", () =>
            Check(Map("....#", ".#.#.", "##..#"), 4, 1, 0, 1)
            ?? Check(Map("#...", "##..", "...#", ".#..", "...."), 1, 4, 1, 0)
            // 아래 세 맵은 이웃을 보는 순서나 f 동률 순서를 바꿔도 "넣을 때 방문 완료" 처리가 틀린다
            ?? Check(Map("...", ".##", "...", ".#.", "..."), 1, 4, 2, 0)
            ?? Check(Map("....", ".##.", ".#.#", "...."), 3, 3, 0, 0)
            ?? Check(Map("....#.", ".#.#..", ".#..#."), 5, 2, 0, 2));

        Run("random-vs-reference", () =>
        {
            uint s = 20261122u;
            System.Func<int, int> rnd = n => { s = s * 1664525u + 1013904223u; return (int)((s >> 8) % (uint)n); };
            for (int run = 0; run < 3000; run++)
            {
                int w = 1 + rnd(12), h = 1 + rnd(12);
                int wallPct = 5 + rnd(45);
                var m = new bool[h, w];
                for (int y = 0; y < h; y++) for (int x = 0; x < w; x++) m[y, x] = rnd(100) >= wallPct;
                string err = Check(m, rnd(w), rnd(h), rnd(w), rnd(h));
                if (err != null) return "무작위 " + run + "회차: " + err;
            }
            return null;
        });
    }
}

