using System;
using System.Collections.Generic;

// 아이템 id 는 1 이상의 정수, amount 는 항상 1 이상으로 들어온다고 가정한다.
public sealed class Inventory
{
    private readonly int[] _slotItem;   // 0 = 빈 슬롯
    private readonly int[] _slotCount;
    private readonly int _maxStack;
    // itemId -> 총 보유량. 슬롯 배열과 항상 같은 값을 가리키도록 Add / Remove 에서만 갱신한다.
    private readonly Dictionary<int, int> _totals = new Dictionary<int, int>();

    public Inventory(int slotCount, int maxStack)
    {
        _slotItem = new int[slotCount];
        _slotCount = new int[slotCount];
        _maxStack = maxStack;
    }

    public int Add(int itemId, int amount)
    {
        int remaining = amount;

        // 1) 이미 있는 같은 아이템 스택을 앞 슬롯부터 채운다.
        for (int i = 0; i < _slotItem.Length && remaining > 0; i++)
        {
            if (_slotItem[i] != itemId) continue;
            int put = Math.Min(_maxStack - _slotCount[i], remaining);
            _slotCount[i] += put;
            remaining -= put;
        }

        // 2) 남은 것은 빈 슬롯에 앞에서부터 새 스택으로 넣는다.
        for (int i = 0; i < _slotItem.Length && remaining > 0; i++)
        {
            if (_slotItem[i] != 0) continue;
            int put = Math.Min(_maxStack, remaining);
            _slotItem[i] = itemId;
            _slotCount[i] = put;
            remaining -= put;
        }

        int added = amount - remaining;
        if (added > 0)
        {
            _totals.TryGetValue(itemId, out int have);
            _totals[itemId] = have + added;
        }
        return remaining;
    }

    public bool Remove(int itemId, int amount)
    {
        // 슬롯을 건드리기 전에 총량으로 먼저 판단해야 "부족하면 아무것도 바꾸지 않는다"가 지켜진다.
        if (!_totals.TryGetValue(itemId, out int have) || have < amount) return false;

        int remaining = amount;
        for (int i = _slotItem.Length - 1; i >= 0 && remaining > 0; i--)
        {
            if (_slotItem[i] != itemId) continue;
            int take = Math.Min(_slotCount[i], remaining);
            _slotCount[i] -= take;
            remaining -= take;
            if (_slotCount[i] == 0) _slotItem[i] = 0; // 빈 슬롯으로 되돌린다
        }

        if (have == amount) _totals.Remove(itemId);
        else _totals[itemId] = have - amount;
        return true;
    }

    public int CountOf(int itemId)
    {
        return _totals.TryGetValue(itemId, out int have) ? have : 0;
    }

    public (int itemId, int count) GetSlot(int index)
    {
        return (_slotItem[index], _slotCount[index]);
    }
}

