using System;

// 시드가 같으면 항상 같은 수열을 내는 작은 난수 생성기(LCG).
public sealed class SeededRng
{
    private uint _state;

    public SeededRng(uint seed) { _state = seed; }

    // 0 .. exclusiveMax-1 범위의 정수. LCG 는 하위 비트의 품질이 낮으므로 상위 비트 쪽을 쓴다.
    public int NextInt(int exclusiveMax)
    {
        _state = _state * 1664525u + 1013904223u;
        return (int)(((ulong)_state * (ulong)exclusiveMax) >> 32);
    }
}

public sealed class LootTable
{
    private readonly int[] _itemIds;
    private readonly int[] _cumulative; // _cumulative[i] = weights[0] + ... + weights[i]

    public int TotalWeight { get; }

    public LootTable(int[] itemIds, int[] weights)
    {
        _itemIds = (int[])itemIds.Clone(); // 호출자가 배열을 나중에 바꿔도 테이블은 그대로다
        _cumulative = new int[weights.Length];
        int sum = 0;
        for (int i = 0; i < weights.Length; i++)
        {
            sum += weights[i];
            _cumulative[i] = sum;
        }
        TotalWeight = sum;
    }

    // "누적 가중치 > roll" 을 만족하는 가장 왼쪽 인덱스를 이분 탐색으로 찾는다.
    public int PickByRoll(int roll)
    {
        int lo = 0, hi = _cumulative.Length - 1; // roll < TotalWeight 이므로 답은 [lo, hi] 안에 있다
        while (lo < hi)
        {
            int mid = lo + (hi - lo) / 2;
            if (_cumulative[mid] > roll) hi = mid; // mid 가 답이거나 답이 더 왼쪽
            else lo = mid + 1;                     // mid 까지는 답이 아니다
        }
        return _itemIds[lo];
    }

    public int Pick(SeededRng rng)
    {
        return PickByRoll(rng.NextInt(TotalWeight));
    }
}

